-- Extend the existing transactional core without changing applied migrations.
CREATE EXTENSION IF NOT EXISTS postgis;
ALTER TABLE app.vineyard ADD COLUMN boundary geography(Polygon,4326);
ALTER TABLE app.ledger DROP CONSTRAINT ledger_account_check;
ALTER TABLE app.ledger ADD CONSTRAINT ledger_account_check CHECK(account IN ('stock','loss','opening','bottling','sample','adjustment','addition','transformation'));
CREATE TABLE app.block_season (tenant_id uuid NOT NULL REFERENCES app.tenant(id), id uuid NOT NULL DEFAULT gen_random_uuid(), vineyard_id uuid NOT NULL, vintage integer NOT NULL CHECK(vintage BETWEEN 1900 AND 2200), management text NOT NULL, planned_kg numeric(20,3) NOT NULL CHECK(planned_kg>=0), UNIQUE(tenant_id,vineyard_id,vintage), FOREIGN KEY(tenant_id,vineyard_id) REFERENCES app.vineyard(tenant_id,id), created_at timestamptz NOT NULL DEFAULT now(), created_by text NOT NULL, PRIMARY KEY(tenant_id,id));
ALTER TABLE app.block_season ENABLE ROW LEVEL SECURITY; ALTER TABLE app.block_season FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_access ON app.block_season USING(tenant_id=app.tenant_id() AND app.is_member(tenant_id) AND app.role()<>'external') WITH CHECK(tenant_id=app.tenant_id() AND app.is_member(tenant_id) AND app.role()<>'external');
CREATE INDEX ON app.block_season(tenant_id,created_at);
CREATE TABLE app.field_operation (tenant_id uuid NOT NULL REFERENCES app.tenant(id), id uuid NOT NULL DEFAULT gen_random_uuid(), vineyard_id uuid NOT NULL, season_id uuid, kind text NOT NULL CHECK(kind IN ('pruning','soil','canopy','observation','protection','irrigation','harvest','other')), description text NOT NULL, performed_at timestamptz NOT NULL, hours numeric(16,3) NOT NULL CHECK(hours>=0), area_ha numeric(12,4) NOT NULL CHECK(area_ha>0), product text NOT NULL DEFAULT '', product_batch text NOT NULL DEFAULT '', quantity numeric(20,3) NOT NULL CHECK(quantity>=0), unit text NOT NULL, operator text NOT NULL, authorization_ref text NOT NULL DEFAULT '', source text NOT NULL DEFAULT '', approved_by text, approved_at timestamptz, version integer NOT NULL DEFAULT 1, FOREIGN KEY(tenant_id,vineyard_id) REFERENCES app.vineyard(tenant_id,id), FOREIGN KEY(tenant_id,season_id) REFERENCES app.block_season(tenant_id,id), created_at timestamptz NOT NULL DEFAULT now(), created_by text NOT NULL, PRIMARY KEY(tenant_id,id));
ALTER TABLE app.field_operation ENABLE ROW LEVEL SECURITY; ALTER TABLE app.field_operation FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_access ON app.field_operation USING(tenant_id=app.tenant_id() AND app.is_member(tenant_id) AND app.role()<>'external') WITH CHECK(tenant_id=app.tenant_id() AND app.is_member(tenant_id) AND app.role()<>'external');
CREATE INDEX ON app.field_operation(tenant_id,created_at);
CREATE TABLE app.maturity_sample (tenant_id uuid NOT NULL REFERENCES app.tenant(id), id uuid NOT NULL DEFAULT gen_random_uuid(), vineyard_id uuid NOT NULL, season_id uuid, code text NOT NULL, sampled_at timestamptz NOT NULL, location text NOT NULL, sugar numeric(16,6), sugar_unit text NOT NULL, acidity numeric(16,6), ph numeric(16,6) CHECK(ph BETWEEN 0 AND 14), method text NOT NULL, quality text NOT NULL CHECK(quality IN ('measured','estimated')), UNIQUE(tenant_id,code), FOREIGN KEY(tenant_id,vineyard_id) REFERENCES app.vineyard(tenant_id,id), FOREIGN KEY(tenant_id,season_id) REFERENCES app.block_season(tenant_id,id), created_at timestamptz NOT NULL DEFAULT now(), created_by text NOT NULL, PRIMARY KEY(tenant_id,id));
ALTER TABLE app.maturity_sample ENABLE ROW LEVEL SECURITY; ALTER TABLE app.maturity_sample FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_access ON app.maturity_sample USING(tenant_id=app.tenant_id() AND app.is_member(tenant_id) AND app.role()<>'external') WITH CHECK(tenant_id=app.tenant_id() AND app.is_member(tenant_id) AND app.role()<>'external');
CREATE INDEX ON app.maturity_sample(tenant_id,created_at);
CREATE TABLE app.resource (tenant_id uuid NOT NULL REFERENCES app.tenant(id), id uuid NOT NULL DEFAULT gen_random_uuid(), name text NOT NULL, kind text NOT NULL CHECK(kind IN ('team','machine','pump','equipment')), description text NOT NULL DEFAULT '', status text NOT NULL CHECK(status IN ('ready','blocked')), version integer NOT NULL DEFAULT 1, UNIQUE(tenant_id,name), created_at timestamptz NOT NULL DEFAULT now(), created_by text NOT NULL, PRIMARY KEY(tenant_id,id));
ALTER TABLE app.resource ENABLE ROW LEVEL SECURITY; ALTER TABLE app.resource FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_access ON app.resource USING(tenant_id=app.tenant_id() AND app.is_member(tenant_id) AND app.role()<>'external') WITH CHECK(tenant_id=app.tenant_id() AND app.is_member(tenant_id) AND app.role()<>'external');
CREATE INDEX ON app.resource(tenant_id,created_at);
CREATE TABLE app.harvest_plan (tenant_id uuid NOT NULL REFERENCES app.tenant(id), id uuid NOT NULL DEFAULT gen_random_uuid(), vineyard_id uuid NOT NULL, vintage integer NOT NULL CHECK(vintage BETWEEN 1900 AND 2200), planned_kg numeric(20,3) NOT NULL CHECK(planned_kg>0), starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL CHECK(ends_at>starts_at), resource_id uuid, target_vessel_id uuid, supplier text NOT NULL, instructions text NOT NULL, status text NOT NULL DEFAULT 'planned' CHECK(status IN ('planned','in_progress','completed','cancelled')), version integer NOT NULL DEFAULT 1, FOREIGN KEY(tenant_id,vineyard_id) REFERENCES app.vineyard(tenant_id,id), FOREIGN KEY(tenant_id,resource_id) REFERENCES app.resource(tenant_id,id), FOREIGN KEY(tenant_id,target_vessel_id) REFERENCES app.vessel(tenant_id,id), created_at timestamptz NOT NULL DEFAULT now(), created_by text NOT NULL, PRIMARY KEY(tenant_id,id));
ALTER TABLE app.harvest_plan ENABLE ROW LEVEL SECURITY; ALTER TABLE app.harvest_plan FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_access ON app.harvest_plan USING(tenant_id=app.tenant_id() AND app.is_member(tenant_id) AND app.role()<>'external') WITH CHECK(tenant_id=app.tenant_id() AND app.is_member(tenant_id) AND app.role()<>'external');
CREATE INDEX ON app.harvest_plan(tenant_id,created_at);
CREATE TABLE app.harvest_yield (tenant_id uuid NOT NULL REFERENCES app.tenant(id), id uuid NOT NULL DEFAULT gen_random_uuid(), harvest_id uuid NOT NULL, lot_id uuid NOT NULL, operation_id uuid NOT NULL, input_kg numeric(20,3) NOT NULL CHECK(input_kg>0), output_l numeric(20,3) NOT NULL CHECK(output_l>0), byproduct_kg numeric(20,3) NOT NULL CHECK(byproduct_kg>=0 AND byproduct_kg<=input_kg), FOREIGN KEY(tenant_id,harvest_id) REFERENCES app.harvest(tenant_id,id), FOREIGN KEY(tenant_id,lot_id) REFERENCES app.lot(tenant_id,id), FOREIGN KEY(tenant_id,operation_id) REFERENCES app.operation(tenant_id,id), created_at timestamptz NOT NULL DEFAULT now(), created_by text NOT NULL, PRIMARY KEY(tenant_id,id));
ALTER TABLE app.harvest_yield ENABLE ROW LEVEL SECURITY; ALTER TABLE app.harvest_yield FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_access ON app.harvest_yield USING(tenant_id=app.tenant_id() AND app.is_member(tenant_id) AND app.role()<>'external') WITH CHECK(tenant_id=app.tenant_id() AND app.is_member(tenant_id) AND app.role()<>'external');
CREATE INDEX ON app.harvest_yield(tenant_id,created_at);
CREATE TABLE app.fermentation_run (tenant_id uuid NOT NULL REFERENCES app.tenant(id), id uuid NOT NULL DEFAULT gen_random_uuid(), lot_id uuid NOT NULL, name text NOT NULL, starts_at timestamptz NOT NULL, ends_at timestamptz, status text NOT NULL CHECK(status IN ('active','completed','paused')), yeast text NOT NULL, target_temperature numeric(12,6), notes text NOT NULL DEFAULT '', version integer NOT NULL DEFAULT 1, CHECK(ends_at IS NULL OR ends_at>=starts_at), FOREIGN KEY(tenant_id,lot_id) REFERENCES app.lot(tenant_id,id), created_at timestamptz NOT NULL DEFAULT now(), created_by text NOT NULL, PRIMARY KEY(tenant_id,id));
ALTER TABLE app.fermentation_run ENABLE ROW LEVEL SECURITY; ALTER TABLE app.fermentation_run FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_access ON app.fermentation_run USING(tenant_id=app.tenant_id() AND app.is_member(tenant_id) AND app.role()<>'external') WITH CHECK(tenant_id=app.tenant_id() AND app.is_member(tenant_id) AND app.role()<>'external');
CREATE INDEX ON app.fermentation_run(tenant_id,created_at);
CREATE TABLE app.lab_rule (tenant_id uuid NOT NULL REFERENCES app.tenant(id), id uuid NOT NULL DEFAULT gen_random_uuid(), name text NOT NULL, lot_id uuid, parameter text NOT NULL, unit text NOT NULL, method text NOT NULL, minimum numeric(16,6), maximum numeric(16,6), max_age_hours integer NOT NULL CHECK(max_age_hours BETWEEN 1 AND 87600), CHECK(minimum IS NOT NULL OR maximum IS NOT NULL), CHECK(minimum IS NULL OR maximum IS NULL OR minimum<=maximum), FOREIGN KEY(tenant_id,lot_id) REFERENCES app.lot(tenant_id,id), created_at timestamptz NOT NULL DEFAULT now(), created_by text NOT NULL, PRIMARY KEY(tenant_id,id));
ALTER TABLE app.lab_rule ENABLE ROW LEVEL SECURITY; ALTER TABLE app.lab_rule FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_access ON app.lab_rule USING(tenant_id=app.tenant_id() AND app.is_member(tenant_id) AND app.role()<>'external') WITH CHECK(tenant_id=app.tenant_id() AND app.is_member(tenant_id) AND app.role()<>'external');
CREATE INDEX ON app.lab_rule(tenant_id,created_at);
CREATE TABLE app.material_item (tenant_id uuid NOT NULL REFERENCES app.tenant(id), id uuid NOT NULL DEFAULT gen_random_uuid(), code text NOT NULL, name text NOT NULL, kind text NOT NULL CHECK(kind IN ('bottle','closure','label','box','treatment','cleaner','other')), unit text NOT NULL CHECK(unit IN ('piece','kg','g','l','ml')), cost_per_unit numeric(16,6) NOT NULL CHECK(cost_per_unit>=0), reorder_at numeric(20,3) NOT NULL CHECK(reorder_at>=0), version integer NOT NULL DEFAULT 1, UNIQUE(tenant_id,code), created_at timestamptz NOT NULL DEFAULT now(), created_by text NOT NULL, PRIMARY KEY(tenant_id,id));
ALTER TABLE app.material_item ENABLE ROW LEVEL SECURITY; ALTER TABLE app.material_item FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_access ON app.material_item USING(tenant_id=app.tenant_id() AND app.is_member(tenant_id) AND app.role()<>'external') WITH CHECK(tenant_id=app.tenant_id() AND app.is_member(tenant_id) AND app.role()<>'external');
CREATE INDEX ON app.material_item(tenant_id,created_at);
CREATE TABLE app.material_movement (tenant_id uuid NOT NULL REFERENCES app.tenant(id), id uuid NOT NULL DEFAULT gen_random_uuid(), material_id uuid NOT NULL, operation_id uuid NOT NULL, quantity numeric(20,3) NOT NULL CHECK(quantity<>0), batch text NOT NULL, reason text NOT NULL, lot_id uuid, bottling_id uuid, FOREIGN KEY(tenant_id,material_id) REFERENCES app.material_item(tenant_id,id), FOREIGN KEY(tenant_id,operation_id) REFERENCES app.operation(tenant_id,id), FOREIGN KEY(tenant_id,lot_id) REFERENCES app.lot(tenant_id,id), FOREIGN KEY(tenant_id,bottling_id) REFERENCES app.bottling(tenant_id,id), created_at timestamptz NOT NULL DEFAULT now(), created_by text NOT NULL, PRIMARY KEY(tenant_id,id));
ALTER TABLE app.material_movement ENABLE ROW LEVEL SECURITY; ALTER TABLE app.material_movement FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_access ON app.material_movement USING(tenant_id=app.tenant_id() AND app.is_member(tenant_id) AND app.role()<>'external') WITH CHECK(tenant_id=app.tenant_id() AND app.is_member(tenant_id) AND app.role()<>'external');
CREATE INDEX ON app.material_movement(tenant_id,created_at);
CREATE TABLE app.cleaning_record (tenant_id uuid NOT NULL REFERENCES app.tenant(id), id uuid NOT NULL DEFAULT gen_random_uuid(), vessel_id uuid, resource_id uuid, performed_at timestamptz NOT NULL, method text NOT NULL, product text NOT NULL, product_batch text NOT NULL DEFAULT '', quantity numeric(20,3) NOT NULL CHECK(quantity>=0), unit text NOT NULL, checklist jsonb NOT NULL, result text NOT NULL CHECK(result IN ('ready','blocked')), verified_by text NOT NULL, CHECK((vessel_id IS NOT NULL)::int+(resource_id IS NOT NULL)::int=1), FOREIGN KEY(tenant_id,vessel_id) REFERENCES app.vessel(tenant_id,id), FOREIGN KEY(tenant_id,resource_id) REFERENCES app.resource(tenant_id,id), created_at timestamptz NOT NULL DEFAULT now(), created_by text NOT NULL, PRIMARY KEY(tenant_id,id));
ALTER TABLE app.cleaning_record ENABLE ROW LEVEL SECURITY; ALTER TABLE app.cleaning_record FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_access ON app.cleaning_record USING(tenant_id=app.tenant_id() AND app.is_member(tenant_id) AND app.role()<>'external') WITH CHECK(tenant_id=app.tenant_id() AND app.is_member(tenant_id) AND app.role()<>'external');
CREATE INDEX ON app.cleaning_record(tenant_id,created_at);
CREATE TABLE app.maintenance_record (tenant_id uuid NOT NULL REFERENCES app.tenant(id), id uuid NOT NULL DEFAULT gen_random_uuid(), vessel_id uuid, resource_id uuid, title text NOT NULL, performed_at timestamptz NOT NULL, due_at timestamptz, findings text NOT NULL, status text NOT NULL CHECK(status IN ('open','doing','done')), version integer NOT NULL DEFAULT 1, CHECK((vessel_id IS NOT NULL)::int+(resource_id IS NOT NULL)::int=1), FOREIGN KEY(tenant_id,vessel_id) REFERENCES app.vessel(tenant_id,id), FOREIGN KEY(tenant_id,resource_id) REFERENCES app.resource(tenant_id,id), created_at timestamptz NOT NULL DEFAULT now(), created_by text NOT NULL, PRIMARY KEY(tenant_id,id));
ALTER TABLE app.maintenance_record ENABLE ROW LEVEL SECURITY; ALTER TABLE app.maintenance_record FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_access ON app.maintenance_record USING(tenant_id=app.tenant_id() AND app.is_member(tenant_id) AND app.role()<>'external') WITH CHECK(tenant_id=app.tenant_id() AND app.is_member(tenant_id) AND app.role()<>'external');
CREATE INDEX ON app.maintenance_record(tenant_id,created_at);
CREATE TABLE app.cost_entry (tenant_id uuid NOT NULL REFERENCES app.tenant(id), id uuid NOT NULL DEFAULT gen_random_uuid(), lot_id uuid, vineyard_id uuid, bottling_id uuid, operation_id uuid NOT NULL, category text NOT NULL CHECK(category IN ('work','material','service','energy','loss','other')), amount numeric(20,6) NOT NULL, currency text NOT NULL CHECK(currency='EUR'), basis text NOT NULL CHECK(basis IN ('planned','actual')), description text NOT NULL, invoice text NOT NULL DEFAULT '', correction_of uuid, FOREIGN KEY(tenant_id,lot_id) REFERENCES app.lot(tenant_id,id), FOREIGN KEY(tenant_id,vineyard_id) REFERENCES app.vineyard(tenant_id,id), FOREIGN KEY(tenant_id,bottling_id) REFERENCES app.bottling(tenant_id,id), FOREIGN KEY(tenant_id,operation_id) REFERENCES app.operation(tenant_id,id), FOREIGN KEY(tenant_id,correction_of) REFERENCES app.cost_entry(tenant_id,id), created_at timestamptz NOT NULL DEFAULT now(), created_by text NOT NULL, PRIMARY KEY(tenant_id,id));
ALTER TABLE app.cost_entry ENABLE ROW LEVEL SECURITY; ALTER TABLE app.cost_entry FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_access ON app.cost_entry USING(tenant_id=app.tenant_id() AND app.is_member(tenant_id) AND app.role()<>'external') WITH CHECK(tenant_id=app.tenant_id() AND app.is_member(tenant_id) AND app.role()<>'external');
