CREATE TABLE app.sensor (tenant_id uuid NOT NULL REFERENCES app.tenant(id), id uuid NOT NULL DEFAULT gen_random_uuid(), name text NOT NULL, lot_id uuid NOT NULL, parameter text NOT NULL CHECK(parameter IN ('temperature','sugar','alcohol','acidity','ph','free_so2')), unit text NOT NULL, method text NOT NULL, token_hash text NOT NULL, enabled boolean NOT NULL DEFAULT true, version integer NOT NULL DEFAULT 1, UNIQUE(tenant_id,token_hash), FOREIGN KEY(tenant_id,lot_id) REFERENCES app.lot(tenant_id,id), created_at timestamptz NOT NULL DEFAULT now(), created_by text NOT NULL, PRIMARY KEY(tenant_id,id));
ALTER TABLE app.sensor ENABLE ROW LEVEL SECURITY; ALTER TABLE app.sensor FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_access ON app.sensor USING(tenant_id=app.tenant_id() AND app.is_member(tenant_id) AND app.role()<>'external') WITH CHECK(tenant_id=app.tenant_id() AND app.is_member(tenant_id) AND app.role()<>'external');
CREATE INDEX ON app.sensor(tenant_id,created_at);
CREATE TABLE app.blend_brief (tenant_id uuid NOT NULL REFERENCES app.tenant(id), id uuid NOT NULL DEFAULT gen_random_uuid(), project_id uuid NOT NULL, style text NOT NULL, budget numeric(20,6), targets jsonb NOT NULL, share_limits jsonb NOT NULL, reference_lot_id uuid, version integer NOT NULL DEFAULT 1, UNIQUE(tenant_id,project_id), FOREIGN KEY(tenant_id,project_id) REFERENCES app.blend_project(tenant_id,id), FOREIGN KEY(tenant_id,reference_lot_id) REFERENCES app.lot(tenant_id,id), created_at timestamptz NOT NULL DEFAULT now(), created_by text NOT NULL, PRIMARY KEY(tenant_id,id));
ALTER TABLE app.blend_brief ENABLE ROW LEVEL SECURITY; ALTER TABLE app.blend_brief FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_access ON app.blend_brief USING(tenant_id=app.tenant_id() AND app.is_member(tenant_id) AND app.role()<>'external') WITH CHECK(tenant_id=app.tenant_id() AND app.is_member(tenant_id) AND app.role()<>'external');
CREATE INDEX ON app.blend_brief(tenant_id,created_at);
CREATE TABLE app.connection (tenant_id uuid NOT NULL REFERENCES app.tenant(id), id uuid NOT NULL DEFAULT gen_random_uuid(), name text NOT NULL, adapter text NOT NULL CHECK(adapter IN ('file','sensor','brightsky','openai-compatible')), capabilities jsonb NOT NULL, authority jsonb NOT NULL, enabled boolean NOT NULL DEFAULT false, version integer NOT NULL DEFAULT 1, UNIQUE(tenant_id,name), created_at timestamptz NOT NULL DEFAULT now(), created_by text NOT NULL, PRIMARY KEY(tenant_id,id));
ALTER TABLE app.connection ENABLE ROW LEVEL SECURITY; ALTER TABLE app.connection FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_access ON app.connection USING(tenant_id=app.tenant_id() AND app.is_member(tenant_id) AND app.role()<>'external') WITH CHECK(tenant_id=app.tenant_id() AND app.is_member(tenant_id) AND app.role()<>'external');
CREATE INDEX ON app.connection(tenant_id,created_at);
CREATE TABLE app.external_reference (tenant_id uuid NOT NULL REFERENCES app.tenant(id), id uuid NOT NULL DEFAULT gen_random_uuid(), connection_id uuid NOT NULL, entity_type text NOT NULL CHECK(entity_type IN ('sku','lot','vineyard','material')), internal_id uuid NOT NULL, external_id text NOT NULL, UNIQUE(tenant_id,connection_id,entity_type,external_id), FOREIGN KEY(tenant_id,connection_id) REFERENCES app.connection(tenant_id,id), created_at timestamptz NOT NULL DEFAULT now(), created_by text NOT NULL, PRIMARY KEY(tenant_id,id));
ALTER TABLE app.external_reference ENABLE ROW LEVEL SECURITY; ALTER TABLE app.external_reference FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_access ON app.external_reference USING(tenant_id=app.tenant_id() AND app.is_member(tenant_id) AND app.role()<>'external') WITH CHECK(tenant_id=app.tenant_id() AND app.is_member(tenant_id) AND app.role()<>'external');
CREATE INDEX ON app.external_reference(tenant_id,created_at);
