GRANT SELECT ON ALL TABLES IN SCHEMA app TO vinea_runtime;
ALTER FUNCTION app.command(uuid,text,text,jsonb) RENAME TO core_command;
REVOKE ALL ON FUNCTION app.core_command(uuid,text,text,jsonb) FROM PUBLIC,vinea_runtime;
